1	/**
2	 * @module features/tv-dashboard/model/tvMath
3	 *
4	 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
5	 * delta semanal, classificação RAG, formatação compacta de moeda,
6	 * staleness e agregações determinísticas usadas pelo hook de dados.
7	 *
8	 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
9	 */
10	
11	import type {
12	  TvBusinessHours,
13	  TvCriticalItem,
14	  TvDateRange,
15	  TvException,
16	  TvExceptionsResult,
17	  TvFreshness,
18	  TvFreshnessLevel,
19	  TvPeriod,
20	  TvRagStatus,
21	  TvRecentMove,
22	  TvStockAlertItem,
23	  TvStoreWeeklyGoal,
24	  TvWeekSegment,
25	  TvWeeklyGoal,
26	} from './types';
27	
28	// ─────────────────────────────────────────────────────────────────────────────
29	// Constantes de negócio
30	// ─────────────────────────────────────────────────────────────────────────────
31	
32	/**
33	 * Janela do DIA COMERCIAL das lojas usada no pró-rata da meta (hora local):
34	 * 08:00–23:00 — lojas abrem às 8h (brunch Lago Sul) e o dia comercial fecha
35	 * às 23h (regra do CTO 2026-06-12; supersede o 10–22 do design.md §1.6
36	 * regra 5). AJUSTÁVEL: se o horário comercial mudar, basta alterar aqui —
37	 * pró-rata, "sem movimentação" e a virada do dia ({@link businessTodayIso})
38	 * derivam daqui.
39	 */
40	export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 8, end: 23 };
41	
42	/**
43	 * Janela de produção da FÁBRICA (design.md §1.6 regra 5 + §5: 06:00–18:00).
44	 * Usada TANTO no RAG da fábrica quanto no alerta visual do card.
45	 */
46	export const TV_FACTORY_HOURS: TvBusinessHours = { start: 6, end: 18 };
47	
48	/** Horas sem movimentação (dentro da janela) que tornam a LOJA âmbar. */
49	export const NO_MOVEMENT_THRESHOLD_HOURS = 3;
50	
51	/** Horas sem bipagem (na janela de produção) que tornam a FÁBRICA âmbar (§5). */
52	export const FACTORY_NO_MOVEMENT_THRESHOLD_HOURS = 2;
53	
54	/**
55	 * Ratio pró-rata (%real / %esperado, em %) abaixo do qual a venda live fica
56	 * ÂMBAR — nunca vermelho (design.md §1.6 regra 6: ratio menor que 0,75).
57	 */
58	export const LIVE_SALES_AMBER_THRESHOLD_PCT = 75;
59	
60	/** Hora local a partir da qual a regra de venda fraca passa a valer (§1.6). */
61	export const LIVE_SALES_AMBER_FROM_HOUR = 11;
62	
63	/** Máximo de linhas exibidas na faixa de exceções. */
64	export const TV_EXCEPTIONS_LIMIT = 7;
65	
66	/** Itens do mini-feed "AGORA" por coluna de unidade. */
67	export const TV_MINI_FEED_SIZE = 3;
68	
69	/** Itens de estoque crítico exibidos na coluna (lista completa no drill-down). */
70	export const TV_CRITICAL_TOP_N = 5;
71	
72	/** Máximo de linhas do feed de movimentações no drill-down por loja. */
73	export const TV_DETAIL_FEED_LIMIT = 50;
74	
75	/**
76	 * Setor canônico de `produtos_master.setor` cujos itens entram nos ALERTAS
77	 * de estoque crítico do painel (regra do CTO 2026-06-05: alertas só do setor
78	 * de produtos vendáveis — EMBALAGENS, INSUMOS, CÂMARA FRIA, ITENS COZINHA,
79	 * MERCEARIA, COMIDAS, PRODUTOS DE LIMPEZA etc. ficam FORA).
80	 *
81	 * Comparar SEMPRE por igualdade exata pós-{@link normalizeSetor} (nunca por
82	 * prefixo/ILIKE: existe o setor "PRODUTOS DE LIMPEZA") — use
83	 * {@link isTvAlertSetor}.
84	 */
85	export const TV_ALERT_SETOR = 'PRODUTOS';
86	
87	/**
88	 * ÚNICA loja cujo faturamento de PDV embute delivery (BSB Shopping): lá o
89	 * iFood/delivery passa pelo caixa Degust junto com o balcão, então o card
90	 * quebra "Loja × Delivery" (R1 da spec tv-acompanhamento-live). Nas demais
91	 * lojas o delivery NÃO entra no PDV — quebra não se aplica.
92	 *
93	 * É `lojas.id` interno (não código Degust). Constante nomeada de propósito:
94	 * exceção de NEGÓCIO documentada, não um hardcode espalhado.
95	 */
96	export const TV_DELIVERY_SPLIT_LOJA_ID = 6;
97	
98	// ─────────────────────────────────────────────────────────────────────────────
99	// Datas (helpers locais, sem dependência de timezone UTC)
100	// ─────────────────────────────────────────────────────────────────────────────
101	
102	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
103	export function toIsoDateLocal(d: Date): string {
104	  const y = d.getFullYear();
105	  const m = String(d.getMonth() + 1).padStart(2, '0');
106	  const day = String(d.getDate()).padStart(2, '0');
107	  return `${y}-${m}-${day}`;
108	}
109	
110	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
111	export function parseIsoDateLocal(iso: string): Date {
112	  const [y, m, d] = iso.split('-').map(Number);
113	  return new Date(y, (m ?? 1) - 1, d ?? 1);
114	}
115	
116	/** Soma `days` dias a uma data, retornando nova instância. */
117	export function addDays(d: Date, days: number): Date {
118	  const out = new Date(d);
119	  out.setDate(out.getDate() + days);
120	  return out;
121	}
122	
123	/**
124	 * Dia COMERCIAL corrente do painel (YYYY-MM-DD local).
125	 *
126	 * O dia comercial vai de 08h a 23h ({@link TV_BUSINESS_HOURS}): a partir
127	 * das 23h o painel VIRA para o dia seguinte — tudo zera e o novo dia
128	 * começa — então `now` com hora ≥ 23 retorna AMANHÃ. Vendas de madrugada
129	 * (00h–05h) pertencem ao caixa do dia ANTERIOR (mesma convenção de
130	 * {@link TV_OVERNIGHT_END_HOUR}/{@link businessHourRank}): nesse horário o
131	 * dia comercial corrente é o próprio dia-calendário, ainda zerado até a
132	 * abertura das 08h — os totais do dia fechado ficam acessíveis no
133	 * histórico (◀).
134	 */
135	export function businessTodayIso(now: Date): string {
136	  return now.getHours() >= TV_BUSINESS_HOURS.end
137	    ? toIsoDateLocal(addDays(now, 1))
138	    : toIsoDateLocal(now);
139	}
140	
141	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
142	export function formatLaggedDateLabel(isoDate: string): string {
143	  const d = parseIsoDateLocal(isoDate);
144	  const dd = String(d.getDate()).padStart(2, '0');
145	  const mm = String(d.getMonth() + 1).padStart(2, '0');
146	  return `até ${dd}/${mm}`;
147	}
148	
149	/**
150	 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
151	 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
152	 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
153	 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
154	 */
155	export function parseBrDateTime(value: string | null | undefined): Date | null {
156	  if (!value) return null;
157	  const m = value.match(
158	    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
159	  );
160	  if (m) {
161	    const [, dd, mm, yyyy, hh, mi, ss] = m;
162	    const month = Number(mm);
163	    const day = Number(dd);
164	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
165	    return new Date(
166	      Number(yyyy),
167	      month - 1,
168	      day,
169	      Number(hh),
170	      Number(mi),
171	      ss ? Number(ss) : 0,
172	    );
173	  }
174	  const fallback = new Date(value);
175	  return Number.isNaN(fallback.getTime()) ? null : fallback;
176	}
177	
178	/**
179	 * Parser do `ultima_atualizacao` do flash-vendas Degust, cujo formato de
180	 * data DEPENDE da culture do servidor da API: historicamente chegava como
181	 * "DD/MM/YYYY HH:mm:ss" (pt-BR), mas em 2026-06-12 o payload real veio
182	 * "06/12/2026 13:17:00" — MM/DD/YYYY (en-US). Ler cegamente como DD/MM
183	 * jogava o flash pra 6/dez e o gate da virada do dia zerava TODOS os cards.
184	 *
185	 * Estratégia: gera as DUAS interpretações ("A/B" como dia/mês E como
186	 * mês/dia, descartando inválidas — mês 13, 31/02 etc.) e escolhe a que cai
187	 * na janela plausível [now−3d, now+1d]: flash é dado quase-live, nunca está
188	 * a semanas do relógio. As duas leituras distam ≥28 dias entre si, então no
189	 * máximo UMA cai na janela — exceto quando A === B (são idênticas). Se
190	 * nenhuma cair (dado muito stale), devolve a mais próxima de `now`: data
191	 * parseável porém velha é problema de FRESHNESS, não de parsing. Sem
192	 * leitura válida → null.
193	 */
194	export function parseDegustFlashDateTime(
195	  raw: string | null | undefined,
196	  now: Date,
197	): Date | null {
198	  if (!raw) return null;
199	  const m = raw.match(
200	    /^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/,
201	  );
202	  if (!m) return null;
203	  const [, aStr, bStr, yyyy, hh, mi, ss] = m;
204	  const a = Number(aStr);
205	  const b = Number(bStr);
206	  const build = (day: number, month: number): Date | null => {
207	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
208	    const d = new Date(
209	      Number(yyyy),
210	      month - 1,
211	      day,
212	      Number(hh),
213	      Number(mi),
214	      ss ? Number(ss) : 0,
215	    );
216	    // Overflow de dia no mês (31/02 → vira 03/03) = leitura inválida
217	    if (d.getMonth() !== month - 1 || d.getDate() !== day) return null;
218	    return d;
219	  };
220	
221	  const candidates: Date[] = [];
222	  const asDdMm = build(a, b);
223	  if (asDdMm) candidates.push(asDdMm);
224	  if (a !== b) {
225	    const asMmDd = build(b, a);
226	    if (asMmDd) candidates.push(asMmDd);
227	  }
228	  if (candidates.length === 0) return null;
229	
230	  const DAY_MS = 86_400_000;
231	  const inWindow = candidates.filter(
232	    (d) =>
233	      d.getTime() >= now.getTime() - 3 * DAY_MS &&
234	      d.getTime() <= now.getTime() + DAY_MS,
235	  );
236	  const pool = inWindow.length > 0 ? inWindow : candidates;
237	  return pool.reduce((best, d) =>
238	    Math.abs(d.getTime() - now.getTime()) <
239	    Math.abs(best.getTime() - now.getTime())
240	      ? d
241	      : best,
242	  );
243	}
244	
245	/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
246	export function timeHHMMFromIso(iso: string | null | undefined): string {
247	  if (!iso) return '—';
248	  const d = new Date(iso);
249	  if (Number.isNaN(d.getTime())) return '—';
250	  const hh = String(d.getHours()).padStart(2, '0');
251	  const mm = String(d.getMinutes()).padStart(2, '0');
252	  return `${hh}:${mm}`;
253	}
254	
255	// ─────────────────────────────────────────────────────────────────────────────
256	// Ranges do filtro global de período (v3) — datas LOCAIS, puras e testáveis
257	// ─────────────────────────────────────────────────────────────────────────────
258	
259	/**
260	 * Range do filtro global (fechado [from, to], YYYY-MM-DD local):
261	 * - `today`: hoje → hoje;
262	 * - `week`: segunda-feira da semana corrente → hoje;
263	 * - `month`: dia 1º do mês corrente → hoje.
264	 */
265	export function periodRange(period: TvPeriod, now: Date): TvDateRange {
266	  const today = toIsoDateLocal(now);
267	  if (period === 'today') return { from: today, to: today };
268	  if (period === 'week') {
269	    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
270	    const dowFromMonday = (now.getDay() + 6) % 7;
271	    const monday = addDays(now, -dowFromMonday);
272	    return { from: toIsoDateLocal(monday), to: today };
273	  }
274	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
275	  return { from: toIsoDateLocal(firstOfMonth), to: today };
276	}
277	
278	/**
279	 * Período ANTERIOR equivalente para comparativos do filtro global:
280	 * - `today`: ontem → ontem;
281	 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
282	 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
283	 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
284	 */
285	export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
286	  if (period === 'today') {
287	    const yesterday = toIsoDateLocal(addDays(now, -1));
288	    return { from: yesterday, to: yesterday };
289	  }
290	  if (period === 'week') {
291	    const dowFromMonday = (now.getDay() + 6) % 7;
292	    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
293	    return {
294	      from: toIsoDateLocal(mondayLastWeek),
295	      to: toIsoDateLocal(addDays(now, -7)),
296	    };
297	  }
298	  const y = now.getFullYear();
299	  const m = now.getMonth();
300	  const firstPrev = new Date(y, m - 1, 1);
301	  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
302	  const lastDayPrevMonth = new Date(y, m, 0).getDate();
303	  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
304	  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
305	}
306	
307	/**
308	 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
309	 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
310	 */
311	export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
312	  const from = parseIsoDateLocal(range.from);
313	  const to = parseIsoDateLocal(range.to);
314	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
315	  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
316	  return {
317	    from: toIsoDateLocal(addDays(from, -days)),
318	    to: toIsoDateLocal(addDays(to, -days)),
319	  };
320	}
321	
322	/**
323	 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
324	 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
325	 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
326	 * (exclusivo — usar `.lt`, nunca `.lte`).
327	 */
328	export function rangeToLocalDayBounds(range: TvDateRange): {
329	  startIso: string;
330	  endExclusiveIso: string;
331	} {
332	  const start = parseIsoDateLocal(range.from);
333	  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
334	  return {
335	    startIso: start.toISOString(),
336	    endExclusiveIso: endExclusive.toISOString(),
337	  };
338	}
339	
340	/**
341	 * Range do filtro global DESLOCADO `offset` períodos no tempo (R2 —
342	 * histórico navegável). Offset 0 = comportamento de {@link periodRange}
343	 * (período corrente, parcial até hoje). Offset −n = período PASSADO
344	 * COMPLETO n posições atrás:
345	 * - `today`: o dia inteiro n dias atrás;
346	 * - `week`: a semana seg-dom COMPLETA n semanas atrás;
347	 * - `month`: o mês-calendário COMPLETO n meses atrás.
348	 *
349	 * Offset positivo não é suportado (não há futuro a navegar) — tratado
350	 * como 0 por segurança.
351	 */
352	export function shiftedPeriodRange(
353	  period: TvPeriod,
354	  offset: number,
355	  now: Date,
356	): TvDateRange {
357	  if (offset >= 0) return periodRange(period, now);
358	  if (period === 'today') {
359	    const day = toIsoDateLocal(addDays(now, offset));
360	    return { from: day, to: day };
361	  }
362	  if (period === 'week') {
363	    const dowFromMonday = (now.getDay() + 6) % 7;
364	    const monday = addDays(now, -dowFromMonday + offset * 7);
365	    return { from: toIsoDateLocal(monday), to: toIsoDateLocal(addDays(monday, 6)) };
366	  }
367	  const first = new Date(now.getFullYear(), now.getMonth() + offset, 1);
368	  // `new Date(y, m+1, 0)` = último dia do mês `m`
369	  const last = new Date(now.getFullYear(), now.getMonth() + offset + 1, 0);
370	  return { from: toIsoDateLocal(first), to: toIsoDateLocal(last) };
371	}
372	
373	// ─────────────────────────────────────────────────────────────────────────────
374	// Meta mensal — semanas seg-dom recortadas ao mês + redistribuição (R4)
375	// ─────────────────────────────────────────────────────────────────────────────
376	
377	/**
378	 * Segmentos seg-dom de um mês, RECORTADOS aos limites do mês: o primeiro
379	 * e o último podem ter menos de 7 dias (mês que começa/termina no meio da
380	 * semana). `index` é 1-based ("Semana 1").
381	 *
382	 * @param year - Ano (ex.: 2026).
383	 * @param monthIndex0 - Mês 0-based (convenção JS `Date.getMonth()`).
384	 */
385	export function monthWeekSegments(
386	  year: number,
387	  monthIndex0: number,
388	): TvWeekSegment[] {
389	  const lastDay = new Date(year, monthIndex0 + 1, 0).getDate();
390	  const segments: TvWeekSegment[] = [];
391	  let day = 1;
392	  let index = 1;
393	  while (day <= lastDay) {
394	    const start = new Date(year, monthIndex0, day);
395	    const dowFromMonday = (start.getDay() + 6) % 7;
396	    const endDay = Math.min(day + (6 - dowFromMonday), lastDay);
397	    segments.push({
398	      index,
399	      from: toIsoDateLocal(start),
400	      to: toIsoDateLocal(new Date(year, monthIndex0, endDay)),
401	      days: endDay - day + 1,
402	    });
403	    day = endDay + 1;
404	    index += 1;
405	  }
406	  return segments;
407	}
408	
409	/**
410	 * Metas semanais do mês de `now` com REDISTRIBUIÇÃO iterativa da meta
411	 * mensal (que é fixa): para cada segmento, em ordem,
412	 * `target = (metaMensal − comprometido) × dias do segmento ÷ dias restantes`,
413	 * onde "comprometido" acumula o REALIZADO das semanas já encerradas e o
414	 * TARGET das semanas correntes/futuras (assume on-target dali em diante).
415	 *
416	 * Consequências (A4 da spec):
417	 * - semana que não bate a meta ⇒ targets das seguintes SOBEM;
418	 * - semana que supera ⇒ targets das seguintes DESCEM;
419	 * - invariante: realizado das semanas passadas + soma dos targets
420	 *   restantes = metaMensal, sempre (targets podem ficar negativos se o
421	 *   realizado já passou da meta — honesto, sem clamp).
422	 *
423	 * `achieved` = soma de `realizadoPorDia` nos dias do segmento (semanas
424	 * passadas e corrente); null para semanas futuras (sem dados ainda).
425	 */
426	export function weeklyTargets(
427	  metaMensal: number,
428	  realizadoPorDia: Map<string, number>,
429	  now: Date,
430	): TvWeeklyGoal[] {
431	  const segments = monthWeekSegments(now.getFullYear(), now.getMonth());
432	  const todayIso = toIsoDateLocal(now);
433	  const sumSegment = (seg: TvWeekSegment): number => {
434	    let sum = 0;
435	    let d = parseIsoDateLocal(seg.from);
436	    for (let i = 0; i < seg.days; i += 1) {
437	      sum += realizadoPorDia.get(toIsoDateLocal(d)) ?? 0;
438	      d = addDays(d, 1);
439	    }
440	    return sum;
441	  };
442	
443	  let committed = 0;
444	  let daysRemaining = segments.reduce((s, seg) => s + seg.days, 0);
445	  const out: TvWeeklyGoal[] = [];
446	  for (const seg of segments) {
447	    const target =
448	      daysRemaining > 0 ? ((metaMensal - committed) * seg.days) / daysRemaining : 0;
449	    const isPast = seg.to < todayIso;
450	    const isCurrent = seg.from <= todayIso && todayIso <= seg.to;
451	    const achieved = isPast || isCurrent ? sumSegment(seg) : null;
452	    out.push({ segment: seg, target, achieved, isCurrent });
453	    // Passadas comprometem o REAL (déficit/superávit redistribui);
454	    // corrente/futuras comprometem o TARGET (projeção on-target).
455	    committed += isPast ? (achieved ?? 0) : target;
456	    daysRemaining -= seg.days;
457	  }
458	  return out;
459	}
460	
461	/**
462	 * Meta semanal de UMA loja na SEMANA CORRENTE: aplica {@link weeklyTargets}
463	 * (mesma redistribuição da meta mensal usada no monthProgress da rede) ao
464	 * realizado diário da loja e extrai o segmento corrente.
465	 *
466	 * - `target` = meta redistribuída da semana corrente (semana 1 abaixo da
467	 *   meta ⇒ target sobe; acima ⇒ desce);
468	 * - `achieved` = soma do realizado nos dias do segmento corrente (segunda →
469	 *   agora — dias futuros não têm entrada no mapa e contam 0);
470	 * - `pct` = achieved/target × 100, null se target ≤ 0 (sem % honesto).
471	 *
472	 * Retorna null quando não há meta mensal positiva cadastrada ou quando
473	 * `now` está fora de qualquer segmento do mês (não acontece na prática).
474	 */
475	export function currentWeekGoal(
476	  metaMensal: number | null | undefined,
477	  realizadoPorDia: Map<string, number>,
478	  now: Date,
479	): TvStoreWeeklyGoal | null {
480	  if (metaMensal == null || metaMensal <= 0) return null;
481	  const current = weeklyTargets(metaMensal, realizadoPorDia, now).find(
482	    (w) => w.isCurrent,
483	  );
484	  if (!current) return null;
485	  const achieved = current.achieved ?? 0;
486	  return {
487	    target: current.target,
488	    achieved,
489	    pct: current.target > 0 ? (achieved / current.target) * 100 : null,
490	  };
491	}
492	
493	/**
494	 * Fração ESPERADA da semana corrente já decorrida em `now` — análoga ao
495	 * `expectedMonthPct` da barra mensal (dias inteiros; HOJE conta inteiro,
496	 * mesmo padrão de `now.getDate() / daysInMonth`). A "semana" é o segmento
497	 * seg-dom do mês CORRENTE recortado por {@link monthWeekSegments} (mesmo
498	 * recorte de {@link weeklyTargets}/{@link currentWeekGoal}).
499	 *
500	 * Uso: pace-ajustar a COR da meta semanal (`ratio = %real / %esperado`),
501	 * consistente com a barra mensal — começo de semana no ritmo NÃO fica
502	 * vermelho. O % numérico exibido segue sendo o real (achieved/target).
503	 *
504	 * Retorna 1 se `now` não cair em nenhum segmento (defensivo — na prática
505	 * todo dia do mês pertence a um segmento).
506	 */
507	export function expectedWeekFraction(now: Date): number {
508	  const todayIso = toIsoDateLocal(now);
509	  const segment = monthWeekSegments(now.getFullYear(), now.getMonth()).find(
510	    (s) => s.from <= todayIso && todayIso <= s.to,
511	  );
512	  if (!segment) return 1;
513	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas)
514	  const elapsedDays =
515	    Math.round(
516	      (parseIsoDateLocal(todayIso).getTime() -
517	        parseIsoDateLocal(segment.from).getTime()) /
518	        86_400_000,
519	    ) + 1;
520	  return Math.min(1, elapsedDays / segment.days);
521	}
522	
523	// ─────────────────────────────────────────────────────────────────────────────
524	// Curva horária (R5) + projeção de fim de mês (R3)
525	// ─────────────────────────────────────────────────────────────────────────────
526	
527	/**
528	 * Hora-limite da madrugada no DIA COMERCIAL: buckets 00h–05h pertencem ao
529	 * FIM do dia, não ao começo. O caixa do Degust agrupa por dataCaixa — uma
530	 * venda às 02:00 tem dataCaixa do dia anterior (é o fechamento da noite),
531	 * então na curva horária ela vem DEPOIS das 23h, nunca antes da manhã.
532	 *
533	 * NÃO atrelar este corte a {@link TV_BUSINESS_HOURS}.start: a abertura
534	 * comercial (08h — brunch Lago Sul vende com chaves reais "08"/"09" no
535	 * byHour) é regra de meta/pró-rata; este corte só separa madrugada de
536	 * manhã na curva horária — 06h é seguro abaixo de qualquer abertura real.
537	 */
538	export const TV_OVERNIGHT_END_HOUR = 6;
539	
540	/**
541	 * Rank de uma hora-calendário dentro do DIA COMERCIAL: madrugada (00–05)
542	 * desloca +24 para ordenar DEPOIS das 23h. Sequência resultante:
543	 * 06, 07, …, 23, 24 (=00h), 25 (=01h), …, 29 (=05h).
544	 */
545	export function businessHourRank(hour: number): number {
546	  return hour < TV_OVERNIGHT_END_HOUR ? hour + 24 : hour;
547	}
548	
549	/**
550	 * Base "ontem até a MESMA hora" usando a curva horária REAL do dia de
551	 * referência: `prevDayTotal` × fração, onde fração = cumulativo de
552	 * `prevDayByHour` até HH:mm ÷ cumulativo total. A hora corrente entra com
553	 * fração linear do minuto dentro da hora (15:30 → metade do bucket "15").
554	 *
555	 * A curva é usada APENAS como fração (kits têm valorUnitario 0 na fonte) —
556	 * o valor absoluto vem sempre do total oficial `prevDayTotal`.
557	 *
558	 * O cumulativo segue a ordem do DIA COMERCIAL ({@link businessHourRank}):
559	 * buckets da madrugada (00h–05h, dataCaixa do dia anterior — fechamento da
560	 * noite) ordenam DEPOIS das 23h, e a hora corrente também é ranqueada —
561	 * às 00:30 o ponto de corte é 24,5 (fim do dia comercial corrente), não
562	 * 0,5. Sem isso, uma venda às 02h de ontem inflava a base da MANHÃ de hoje.
563	 *
564	 * Retorna null quando não há base honesta — curva ausente/vazia, cumulativo
565	 * total 0, total não positivo ou fração 0 (antes da 1ª venda do dia de
566	 * referência) — para o caller cair no fallback pró-rata linear existente.
567	 */
568	export function hourlyPaceBase(
569	  prevDayTotal: number,
570	  prevDayByHour: Record<string, number> | undefined,
571	  now: Date,
572	): number | null {
573	  if (prevDayTotal <= 0 || !prevDayByHour) return null;
574	  const buckets: Array<[number, number]> = [];
575	  for (const [hh, value] of Object.entries(prevDayByHour)) {
576	    const hour = Number(hh);
577	    if (!Number.isInteger(hour) || hour < 0 || hour > 23) continue;
578	    buckets.push([businessHourRank(hour), value]);
579	  }
580	  const cumTotal = buckets.reduce((s, [, v]) => s + v, 0);
581	  if (cumTotal <= 0) return null;
582	  const currentRank = businessHourRank(now.getHours());
583	  const minuteFraction = (now.getMinutes() + now.getSeconds() / 60) / 60;
584	  let cumNow = 0;
585	  for (const [rank, value] of buckets) {
586	    if (rank < currentRank) cumNow += value;
587	    else if (rank === currentRank) cumNow += value * minuteFraction;
588	  }
589	  if (cumNow <= 0) return null;
590	  return prevDayTotal * (cumNow / cumTotal);
591	}
592	
593	/**
594	 * Projeção de fim de mês por run-rate (mtd ÷ dias decorridos × dias do
595	 * mês), com "dias decorridos" = dias COMPLETOS decorridos + 1 (hoje conta
596	 * inteiro — sem fração de dia, decisão da spec). No dia 1º a projeção é
597	 * o run-rate de 1 dia (`mtd × diasDoMês`).
598	 */
599	export function monthEndProjection(mtdTotal: number, now: Date): number {
600	  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
601	  const daysElapsed = now.getDate();
602	  return (mtdTotal / daysElapsed) * daysInMonth;
603	}
604	
605	// ─────────────────────────────────────────────────────────────────────────────
606	// Pró-rata da meta
607	// ─────────────────────────────────────────────────────────────────────────────
608	
609	/**
610	 * Fração linear do dia comercial já decorrida em `now`.
611	 *
612	 * - Antes da abertura → 0 (não há venda esperada ainda).
613	 * - Depois do fechamento → 1 (meta integral esperada).
614	 * - Dentro da janela → interpolação linear simples (pró-rata).
615	 */
616	export function businessDayFraction(
617	  now: Date,
618	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
619	): number {
620	  const { start, end } = hours;
621	  if (end <= start) {
622	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
623	    return now.getHours() >= end ? 1 : 0;
624	  }
625	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
626	  if (h <= start) return 0;
627	  if (h >= end) return 1;
628	  return (h - start) / (end - start);
629	}
630	
631	/**
632	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
633	 *
634	 * Retorna null quando não dá para calcular com honestidade:
635	 * - meta ausente/zerada (sem referência), ou
636	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
637	 */
638	export function pctOfProRataTarget(
639	  sold: number,
640	  dailyTarget: number | null | undefined,
641	  now: Date,
642	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
643	): number | null {
644	  if (dailyTarget == null || dailyTarget <= 0) return null;
645	  const fraction = businessDayFraction(now, hours);
646	  if (fraction <= 0) return null;
647	  return (sold / (dailyTarget * fraction)) * 100;
648	}
649	
650	/**
651	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
652	 * cujo dia de referência já encerrou.
653	 */
654	export function pctOfFullDayTarget(
655	  sold: number,
656	  dailyTarget: number | null | undefined,
657	): number | null {
658	  if (dailyTarget == null || dailyTarget <= 0) return null;
659	  return (sold / dailyTarget) * 100;
660	}
661	
662	// ─────────────────────────────────────────────────────────────────────────────
663	// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
664	// ─────────────────────────────────────────────────────────────────────────────
665	
666	/**
667	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
668	 * passada, período anterior do filtro…). Retorna null quando a base é
669	 * ausente ou não positiva — sem base honesta, sem número inventado.
670	 */
671	export function relativeDelta(
672	  current: number,
673	  base: number | null | undefined,
674	): number | null {
675	  if (base == null || base <= 0) return null;
676	  return ((current - base) / base) * 100;
677	}
678	
679	/**
680	 * Delta % vs MESMO DIA da semana anterior — caso particular de
681	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
682	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
683	 */
684	export function weekOverWeekDelta(
685	  current: number,
686	  lastWeek: number | null | undefined,
687	): number | null {
688	  return relativeDelta(current, lastWeek);
689	}
690	
691	/**
692	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
693	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
694	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
695	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
696	 * usada no pró-rata da meta, por consistência).
697	 *
698	 * Comparar dia parcial com dia completo inflava a queda de manhã.
699	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
700	 *
701	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
702	 * (fração 0 — não há ponto de comparação honesto).
703	 */
704	export function proRataDayBase(
705	  referenceDayTotal: number | null | undefined,
706	  now: Date,
707	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
708	): number | null {
709	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
710	  const fraction = businessDayFraction(now, hours);
711	  if (fraction <= 0) return null;
712	  return referenceDayTotal * fraction;
713	}
714	
715	/**
716	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
717	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
718	 * a API existente).
719	 */
720	export function proRataLastWeekBase(
721	  lastWeek: number | null | undefined,
722	  now: Date,
723	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
724	): number | null {
725	  return proRataDayBase(lastWeek, now, hours);
726	}
