728	// ─────────────────────────────────────────────────────────────────────────────
729	// RAG da loja
730	// ─────────────────────────────────────────────────────────────────────────────
731	
732	/** Entrada da classificação RAG de uma unidade. */
733	export interface StoreRagInput {
734	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
735	  stockOutCount: number;
736	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
737	  stockLowCount: number;
738	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
739	  pctMetaProRata: number | null;
740	  /** true quando a unidade tem venda ao vivo (canal Degust). */
741	  isLiveChannel: boolean;
742	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
743	  lastMovementAt: Date | string | null;
744	  /** Instante da avaliação. */
745	  now: Date;
746	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
747	  hours?: TvBusinessHours;
748	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
749	  noMovementThresholdHours?: number;
750	}
751	
752	/**
753	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
754	 *
755	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
756	 *   não faz sentido alertar madrugada sem bipagem.
757	 * - A referência é clampada ao início da janela de hoje: se a última
758	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
759	 */
760	export function hoursWithoutMovementInWindow(
761	  lastMovementAt: Date | string | null,
762	  now: Date,
763	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
764	): number | null {
765	  const fraction = businessDayFraction(now, hours);
766	  if (fraction <= 0 || fraction >= 1) return null;
767	  const windowStart = new Date(now);
768	  windowStart.setHours(hours.start, 0, 0, 0);
769	  const last = lastMovementAt
770	    ? new Date(lastMovementAt).getTime()
771	    : Number.NEGATIVE_INFINITY;
772	  const ref = Math.max(last, windowStart.getTime());
773	  return (now.getTime() - ref) / 3_600_000;
774	}
775	
776	/**
777	 * Classificação RAG de uma unidade (management-by-exception).
778	 *
779	 * Regras (design.md §1.6, ordem de precedência):
780	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
781	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
782	 *   manhã, quando o pró-rata ainda é instável).
783	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
784	 *   movimentação há mais que o threshold dentro da janela OU venda live com
785	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
786	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
787	 *   em canal live e com meta cadastrada (pct != null).
788	 * - OK: nenhum desvio — tela calma, sem cor.
789	 */
790	export function classifyStoreRag(input: StoreRagInput): {
791	  status: TvRagStatus;
792	  reasons: string[];
793	} {
794	  const hours = input.hours ?? TV_BUSINESS_HOURS;
795	  const noMovementThreshold =
796	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
797	  const reasons: string[] = [];
798	
799	  // ── Vermelho: só ruptura (item zerado em alerta) ──
800	  if (input.stockOutCount > 0) {
801	    reasons.push(
802	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
803	    );
804	    return { status: 'red', reasons };
805	  }
806	
807	  // ── Âmbar ──
808	  if (input.stockLowCount > 0) {
809	    reasons.push(
810	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
811	    );
812	  }
813	  const gapHours = hoursWithoutMovementInWindow(
814	    input.lastMovementAt,
815	    input.now,
816	    hours,
817	  );
818	  if (gapHours !== null && gapHours > noMovementThreshold) {
819	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
820	  }
821	  if (
822	    input.isLiveChannel &&
823	    input.pctMetaProRata !== null &&
824	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
825	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
826	  ) {
827	    reasons.push(
828	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
829	    );
830	  }
831	  if (reasons.length > 0) return { status: 'amber', reasons };
832	
833	  return { status: 'ok', reasons: [] };
834	}
835	
836	/** Entrada de {@link buildNoMovementException}. */
837	export interface NoMovementExceptionInput {
838	  lojaId: number;
839	  lojaNome: string;
840	  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
841	  lastMovementAt: Date | string | null;
842	  now: Date;
843	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
844	  hours?: TvBusinessHours;
845	  /** Threshold em horas (default lojas 3h; fábrica 2h). */
846	  thresholdHours?: number;
847	}
848	
849	/**
850	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
851	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
852	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
853	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
854	 * Retorna null quando não há gap acima do threshold dentro da janela.
855	 */
856	export function buildNoMovementException(
857	  input: NoMovementExceptionInput,
858	): TvException | null {
859	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
860	  const gap = hoursWithoutMovementInWindow(
861	    input.lastMovementAt,
862	    input.now,
863	    input.hours ?? TV_BUSINESS_HOURS,
864	  );
865	  if (gap === null || gap <= threshold) return null;
866	  return {
867	    id: `no-movement:${input.lojaId}`,
868	    kind: 'no-movement',
869	    severity: 'amber',
870	    lojaId: input.lojaId,
871	    lojaNome: input.lojaNome,
872	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
873	  };
874	}
