876	// ─────────────────────────────────────────────────────────────────────────────
877	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
878	// ─────────────────────────────────────────────────────────────────────────────
879	
880	function trimOneDecimal(v: number): string {
881	  const rounded = Math.round(v * 10) / 10;
882	  return rounded.toLocaleString('pt-BR', {
883	    minimumFractionDigits: 0,
884	    maximumFractionDigits: 1,
885	  });
886	}
887	
888	/**
889	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
890	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
891	 * Valores negativos preservam o sinal ("-R$ 1,2k").
892	 */
893	export function formatCompactBRL(value: number): string {
894	  const sign = value < 0 ? '-' : '';
895	  const abs = Math.abs(value);
896	  // Bump pra M quando o arredondamento em k chegaria a 1000k
897	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
898	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
899	  }
900	  if (abs >= 1_000) {
901	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
902	  }
903	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
904	}
