906	// ─────────────────────────────────────────────────────────────────────────────
907	// Staleness
908	// ─────────────────────────────────────────────────────────────────────────────
909	
910	/**
911	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
912	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
913	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
914	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
915	 */
916	export function classifyStaleness(
917	  lastUpdatedAt: Date | string | number | null | undefined,
918	  expectedIntervalMs: number,
919	  now: Date,
920	): TvFreshnessLevel {
921	  if (lastUpdatedAt == null) return 'very-stale';
922	  const ts = new Date(lastUpdatedAt).getTime();
923	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
924	  const age = now.getTime() - ts;
925	  if (age < 2 * expectedIntervalMs) return 'fresh';
926	  if (age < 6 * expectedIntervalMs) return 'stale';
927	  return 'very-stale';
928	}
929	
930	/**
931	 * Monta o freshness consolidado a partir dos timestamps CRUS de última
932	 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
933	 *
934	 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
935	 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
936	 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
937	 * parar de avançar além de 2× o intervalo esperado.
938	 */
939	export function buildFreshness(
940	  liveUpdatedAtMs: number,
941	  stockUpdatedAtMs: number,
942	  intervals: { liveMs: number; slowMs: number },
943	  now: Date,
944	): TvFreshness {
945	  const liveUpdatedAt =
946	    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
947	  const stockUpdatedAt =
948	    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
949	  return {
950	    vendasLive: {
951	      updatedAt: liveUpdatedAt,
952	      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
953	      expectedIntervalMs: intervals.liveMs,
954	    },
955	    estoque: {
956	      updatedAt: stockUpdatedAt,
957	      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
958	      expectedIntervalMs: intervals.slowMs,
959	    },
960	    geradoEm: now.toISOString(),
961	  };
962	}
963	
964	// ─────────────────────────────────────────────────────────────────────────────
965	// Exceções — ordenação e corte
966	// ─────────────────────────────────────────────────────────────────────────────
967	
968	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
969	// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
970	const KIND_ORDER: Record<string, number> = {
971	  'stock-out': 0,
972	  'stock-low': 1,
973	  'no-movement': 2,
974	  'stale-data': 3,
975	};
976	
977	/**
978	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
979	 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
980	 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
981	 * contagem do excedente.
982	 */
983	export function sortAndLimitExceptions(
984	  exceptions: TvException[],
985	  limit: number = TV_EXCEPTIONS_LIMIT,
986	): TvExceptionsResult {
987	  const sorted = [...exceptions].sort((a, b) => {
988	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
989	    if (sev !== 0) return sev;
990	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
991	    if (kind !== 0) return kind;
992	    return a.message.localeCompare(b.message, 'pt-BR');
993	  });
994	  return {
995	    items: sorted.slice(0, limit),
996	    overflowCount: Math.max(0, sorted.length - limit),
997	    totalCount: sorted.length,
