1024	export function aggregateMovements(
1025	  rows: MovementRow[],
1026	): Map<number, MovementAggregate> {
1027	  const out = new Map<number, MovementAggregate>();
1028	  for (const row of rows) {
1029	    if (row.loja_id == null) continue;
1030	    let agg = out.get(row.loja_id);
1031	    if (!agg) {
1032	      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
1033	      out.set(row.loja_id, agg);
1034	    }
1035	    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
1036	    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
1037	    if (
1038	      row.data_movimentacao &&
1039	      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
1040	    ) {
