1047	/**
1048	 * Normaliza um valor de `produtos_master.setor` para comparação: trim,
1049	 * minúsculas e remoção de acentos (NFD). O banco tem caixa/acentuação
1050	 * inconsistentes no MESMO setor (ex.: "CÂMARA FRIA" e "Câmara Fria") —
1051	 * toda comparação de setor DEVE passar por aqui.
1052	 */
1053	export function normalizeSetor(value: string | null | undefined): string {
1054	  return (value ?? '')
1055	    .normalize('NFD')
1056	    .replace(/\p{M}/gu, '')
1057	    .trim()
1058	    .toLowerCase();
1059	}
