1086	/**
1087	 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
1088	 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
1089	 * query). Regras (critério existente do projeto, sem schema novo):
1090	 * - SÓ setor {@link TV_ALERT_SETOR} entra em alerta (regra do CTO
1091	 *   2026-06-05: alertas só do setor de produtos vendáveis) — comparação
1092	 *   normalizada client-side porque a caixa no banco é inconsistente;
1093	 * - zerado (vermelho): quantidade ≤ 0 com mínimo definido (positivo);
1094	 * - abaixo do mínimo (âmbar): quantidade entre 0 exclusivo e o mínimo.
1095	 */
1096	export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
1097	  const out = new Map<number, StockDetail>();
1098	  for (const row of rows) {
1099	    if (row.loja_id == null) continue;
1100	    if (!isTvAlertSetor(row.setor)) continue; // fora do setor vendável → sem alerta
1101	    const min = row.quantidade_minima ?? 0;
1102	    if (min <= 0) continue; // sem mínimo definido → sem alerta
1103	    const qty = row.quantidade_atual ?? 0;
1104	    if (qty >= min) continue; // dentro do normal
1105	    let detail = out.get(row.loja_id);
1106	    if (!detail) {
1107	      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
1108	      out.set(row.loja_id, detail);
1109	    }
1110	    const zerado = qty <= 0;
1111	    if (zerado) detail.zerados += 1;
1112	    else detail.abaixoMinimo += 1;
1113	    detail.itens.push({
1114	      produtoNome: row.produtoNome,
1115	      quantidade: qty,
1116	      quantidadeMinima: min,
1117	      zerado,
1118	    });
1119	  }
1120	  return out;
1121	}
