1127	export function buildStockExceptions(
1128	  detailByLoja: Map<number, StockDetail>,
1129	  lojaNomeById: Map<number, string>,
1130	): TvException[] {
1131	  const out: TvException[] = [];
1132	  for (const [lojaId, detail] of detailByLoja) {
1133	    const lojaNome = lojaNomeById.get(lojaId) ?? `Loja ${lojaId}`;
1134	    for (const item of detail.itens) {
1135	      out.push({
1136	        id: `${item.zerado ? 'stock-out' : 'stock-low'}:${lojaId}:${item.produtoNome}`,
1137	        kind: item.zerado ? 'stock-out' : 'stock-low',
1138	        severity: item.zerado ? 'red' : 'amber',
1139	        lojaId,
1140	        lojaNome,
1141	        message: item.zerado
1142	          ? `${item.produtoNome} zerado — ${lojaNome}`
1143	          : `${item.produtoNome} abaixo do mínimo (${item.quantidade}/${item.quantidadeMinima}) — ${lojaNome}`,
1144	        produtoNome: item.produtoNome,
1145	        quantidade: item.quantidade,
1146	        quantidadeMinima: item.quantidadeMinima,
1147	      });
