1164	/**
1165	 * Corrige o `loja_id` das linhas de flash-vendas.
1166	 *
1167	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
1168	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
1169	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
1170	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
1171	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
1172	 *
1173	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
1174	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
1175	 * - Caso contrário → descarta (não corromper outra loja).
1176	 */
1177	export function remapFlashLojaIds(
1178	  rows: FlashRow[],
1179	  degustCodeToLoja: ReadonlyMap<number, number>,
1180	  knownDegustLojaIds: ReadonlySet<number>,
1181	): FlashRow[] {
1182	  const out: FlashRow[] = [];
1183	  for (const row of rows) {
1184	    if (knownDegustLojaIds.has(row.loja_id)) {
1185	      out.push(row);
1186	      continue;
1187	    }
1188	    const mapped = degustCodeToLoja.get(row.loja_id);
1189	    if (mapped != null) {
1190	      out.push({ ...row, loja_id: mapped });
1191	    }
1192	    // não mapeável → descartado de propósito (ver TSDoc)
1193	  }
1194	  return out;
1195	}
