1197	/**
1198	 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
1199	 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
1200	 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
1201	 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
1202	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
1203	 * o drill-down, a lista completa.
1204	 */
1205	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
1206	  const missingFraction = (c: TvCriticalItem): number =>
1207	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
1208	  return items
1209	    .map<TvCriticalItem>((i) => ({
1210	      nome: i.produtoNome,
1211	      quantidade: i.quantidade,
1212	      minima: i.quantidadeMinima,
1213	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
1214	    }))
1215	    .sort((a, b) => {
1216	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
1217	      const diff = missingFraction(b) - missingFraction(a);
1218	      if (diff !== 0) return diff;
1219	      return a.nome.localeCompare(b.nome, 'pt-BR');
1220	    });
1221	}
