1353	// Paginação PostgREST (loop genérico com fetcher injetado — sem I/O próprio)
1354	// ─────────────────────────────────────────────────────────────────────────────
1355	
1356	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
1357	export interface TvPageResult<T> {
1358	  data: T[] | null;
1359	  error: { message: string } | null;
1360	}
1361	
1362	/**
1363	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
1364	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
1365	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
1366	 *
1367	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
1368	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
1369	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
1370	 * sobreporem entre requests.
1371	 */
1372	export async function fetchAllPages<T>(
1373	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
1374	  pageSize = 1000,
1375	): Promise<T[]> {
1376	  const all: T[] = [];
1377	  let offset = 0;
1378	  for (;;) {
1379	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
1380	    if (error) throw error;
1381	    const rows = data ?? [];
1382	    all.push(...rows);
1383	    if (rows.length < pageSize) return all;
1384	    offset += pageSize;
1385	  }
1386	}
