/** Máximo de linhas exibidas na faixa de exceções. */
export const TV_EXCEPTIONS_LIMIT = 7;

/**
 * Minutos sem atualização do flash, dentro do horário comercial e com caixa
 * aberto, que caracterizam PDV dessincronizado — acima da cadência normal
 * ~1h do Degust (RCA Asa Norte 2026-06-19).
 */
export const TV_FLASH_STALE_MINUTES = 90;

/**
 * Detecta flash live defasado de UMA loja: caixa aberto mas a última
 * atualização do POS (lastUpdate) está há mais de thresholdMinutes,
 * DENTRO da janela comercial. Fora da janela ou caixa fechado/sem
 * timestamp → false (defasagem noturna é esperada).
 */
export function detectStaleLiveFlash(params: {
  caixaAberto: boolean | null;
  lastUpdate: Date | null;
  now: Date;
  /** Minutos sem atualização que caracterizam PDV dessincronizado. Default: TV_FLASH_STALE_MINUTES. */
  thresholdMinutes?: number;
  /** Janela comercial para avaliação. Default: TV_BUSINESS_HOURS. */
  hours?: TvBusinessHours;
}): boolean {
  const { caixaAberto, lastUpdate, now } = params;
  const thresholdMinutes = params.thresholdMinutes ?? TV_FLASH_STALE_MINUTES;
  const hours = params.hours ?? TV_BUSINESS_HOURS;

  if (!caixaAberto || !lastUpdate) return false;

  // Só sinaliza dentro da janela comercial (fora = defasagem noturna esperada)
  const fraction = businessDayFraction(now, hours);
  if (fraction <= 0 || fraction >= 1) return false;

  const ageMinutes = (now.getTime() - lastUpdate.getTime()) / 60_000;
  return ageMinutes > thresholdMinutes;
}

