describe('detectStaleLiveFlash', () => {
  // 2026-06-19 14:00 — dentro da janela comercial (8h–23h)
  const now14h = new Date(2026, 5, 19, 14, 0, 0);

  it('retorna true quando caixa aberto e last update há 8h dentro da janela', () => {
    // lastUpdate às 06:00 → 8h antes de 14:00 (> 90min)
    const lastUpdate = new Date(2026, 5, 19, 6, 0, 0);
    expect(
      detectStaleLiveFlash({
        caixaAberto: true,
        lastUpdate,
        now: now14h,
      }),
    ).toBe(true);
  });

  it('retorna false quando última atualização foi recente (10 min atrás)', () => {
    const lastUpdate = new Date(2026, 5, 19, 13, 50, 0);
    expect(
      detectStaleLiveFlash({
        caixaAberto: true,
        lastUpdate,
        now: now14h,
      }),
    ).toBe(false);
  });

  it('retorna false quando fora da janela comercial (02:25 → now às 03:00)', () => {
    // Cenário Asa Norte real: lastUpdate 02:25, now 03:00 → fora da janela (antes das 8h)
    const lastUpdate = new Date(2026, 5, 19, 2, 25, 0);
    const nowEarly = new Date(2026, 5, 19, 3, 0, 0);
    expect(
      detectStaleLiveFlash({
        caixaAberto: true,
        lastUpdate,
        now: nowEarly,
      }),
    ).toBe(false);
  });

  it('retorna false quando caixa fechado, mesmo com defasagem', () => {
    const lastUpdate = new Date(2026, 5, 19, 6, 0, 0);
    expect(
      detectStaleLiveFlash({
        caixaAberto: false,
        lastUpdate,
        now: now14h,
      }),
    ).toBe(false);
  });

  it('retorna false quando caixaAberto é null', () => {
    const lastUpdate = new Date(2026, 5, 19, 6, 0, 0);
    expect(
      detectStaleLiveFlash({
        caixaAberto: null,
        lastUpdate,
        now: now14h,
      }),
    ).toBe(false);
  });

  it('retorna false quando lastUpdate é null', () => {
    expect(
      detectStaleLiveFlash({
        caixaAberto: true,
        lastUpdate: null,
        now: now14h,
      }),
    ).toBe(false);
  });

  it('retorna false quando exatamente no threshold (não ultrapassa)', () => {
    // Exatamente TV_FLASH_STALE_MINUTES atrás → NÃO é stale (precisa ser MAIOR)
    const lastUpdate = new Date(
      now14h.getTime() - TV_FLASH_STALE_MINUTES * 60_000,
    );
    expect(
      detectStaleLiveFlash({
        caixaAberto: true,
        lastUpdate,
        now: now14h,
      }),
    ).toBe(false);
  });

  it('retorna true quando um minuto além do threshold', () => {
    const lastUpdate = new Date(
      now14h.getTime() - (TV_FLASH_STALE_MINUTES + 1) * 60_000,
    );
    expect(
      detectStaleLiveFlash({
        caixaAberto: true,
        lastUpdate,
        now: now14h,
      }),
    ).toBe(true);
  });

  it('respeita thresholdMinutes customizado', () => {
    // 30 min atrás com threshold 20 → stale
    const lastUpdate30 = new Date(now14h.getTime() - 30 * 60_000);
    expect(
      detectStaleLiveFlash({
        caixaAberto: true,
        lastUpdate: lastUpdate30,
        now: now14h,
        thresholdMinutes: 20,
      }),
    ).toBe(true);
    // 30 min atrás com threshold 60 → não stale
    expect(
      detectStaleLiveFlash({
        caixaAberto: true,
        lastUpdate: lastUpdate30,
        now: now14h,
        thresholdMinutes: 60,
      }),
    ).toBe(false);
  });

  it('retorna false quando now está exatamente em TV_BUSINESS_HOURS.end (janela fechada)', () => {
    // 23:00 exato → businessDayFraction retorna 1 → fora da janela
    const nowClose = new Date(2026, 5, 19, 23, 0, 0);
    const lastUpdate = new Date(2026, 5, 19, 20, 0, 0);
    expect(
      detectStaleLiveFlash({
        caixaAberto: true,
        lastUpdate,
        now: nowClose,
      }),
    ).toBe(false);
  });
});

