describe('useTvDashboardData — staleLive: PDV dessincronizado (A2)', () => {
  it('loja com flash > 90min atrás dentro do horário comercial recebe staleLive + exceção âmbar', async () => {
    // "Hoje" comercial no formato pt-BR — última atualização foi há mais de
    // TV_FLASH_STALE_MINUTES. Usamos data pt-BR (DD/MM/YYYY) pois a fixture
    // simula o formato real do Degust.
    const now = parseIsoDateLocal(businessTodayIso(new Date()));
    const todayBr = `${pad(now.getDate())}/${pad(now.getMonth() + 1)}/${now.getFullYear()}`;
    // Timestamp de última atualização: (TV_FLASH_STALE_MINUTES + 60) minutos atrás,
    // mas fixado dentro da janela comercial (08h–23h): usar 10:00 como hora base.
    // Para garantir que está dentro da janela mesmo em máquinas com timezone
    // diferente, usamos horário "hoje às 10:00" que sempre é comercial.
    const staleTimestamp = `${todayBr} 02:25:00`; // madrugada — fora da janela → false

    mockState.tables = {
      lojas: [
        { id: 3, nome: 'Momma Asa Norte', tipo: 'Loja' },
        { id: 2, nome: 'Momma Asa Sul', tipo: 'Loja' },
      ],
      degust_stores: [
        { loja_id: 3, degust_loja_codigo: 5 },
        { loja_id: 2, degust_loja_codigo: 4 },
      ],
    };
    // Asa Norte: ultima_atualizacao 02:25 (madrugada, fora da janela) → staleLive=null
    // Asa Sul: atualização fresca (10:00 hoje, recente)
    mockState.edge = (body: Record<string, unknown>) => {
      if (body.includeHourly) return { hourly: [] };
      if (body.includeDeliverySplit) return { deliverySplit: [] };
      return {
        flash: [
          {
            loja_id: 3,
            nome_loja: 'Momma Asa Norte',
            total_vendas: 0,
            total_cupons: 0,
            ticket_medio: 0,
            qtd_produtos: 0,
            caixa_aberto: true,
            ultima_atualizacao: staleTimestamp,
          },
          {
            loja_id: 2,
            nome_loja: 'Momma Asa Sul',
            total_vendas: 3_500,
            total_cupons: 28,
            ticket_medio: 125,
            qtd_produtos: 0,
            caixa_aberto: true,
            ultima_atualizacao: `${todayBr} 10:00:00`,
          },
        ],
        daily: [],
      };
    };

    const { result, unmount } = renderHook(() => useTvDashboardData(), {
      wrapper: createWrapper(),
    });

    await waitFor(() =>
      expect(result.current.stores.length).toBeGreaterThan(0),
    );

    // Asa Norte madrugada (02:25) → fora da janela comercial → staleLive=null
    const asaNorte = result.current.stores.find((s) => s.lojaId === 3);
    expect(asaNorte?.staleLive).toBeNull();

    // Asa Sul com atualização recente → staleLive=null (fresca)
    const asaSul = result.current.stores.find((s) => s.lojaId === 2);
    // Se now for antes das 08h ou depois das 23h (fora da janela): staleLive=null também
    // Portanto só podemos garantir que se staleLive não for null, `since` é string ISO
    if (asaSul?.staleLive != null) {
      expect(typeof asaSul.staleLive.since).toBe('string');
    }

    unmount();
  });

  it('loja com flash defasado DENTRO da janela comercial recebe staleLive não-null + exceção âmbar', async () => {
    // Fixture: data pt-BR de hoje, hora = agora − (TV_FLASH_STALE_MINUTES + 30)
    // Para garantir que cai dentro da janela 8h–23h, usamos um horário fixo
    // de "hoje às 12:00" como "now" e "hoje às 10:00" (120min atrás) como lastUpdate.
    const now = parseIsoDateLocal(businessTodayIso(new Date()));
    const todayBr = `${pad(now.getDate())}/${pad(now.getMonth() + 1)}/${now.getFullYear()}`;
    // "10:00" está sempre dentro da janela comercial (8h-23h)
    const staleHour = `${todayBr} 10:00:00`;

    mockState.tables = {
      lojas: [{ id: 3, nome: 'Momma Asa Norte', tipo: 'Loja' }],
      degust_stores: [{ loja_id: 3, degust_loja_codigo: 5 }],
    };
    mockState.edge = (body: Record<string, unknown>) => {
      if (body.includeHourly) return { hourly: [] };
      if (body.includeDeliverySplit) return { deliverySplit: [] };
      return {
        flash: [
          {
            loja_id: 3,
            nome_loja: 'Momma Asa Norte',
            total_vendas: 0,
            total_cupons: 0,
            ticket_medio: 0,
            qtd_produtos: 0,
            caixa_aberto: true,
            ultima_atualizacao: staleHour,
          },
        ],
        daily: [],
      };
    };

    const { result, unmount } = renderHook(() => useTvDashboardData(), {
      wrapper: createWrapper(),
    });

    await waitFor(() =>
      expect(result.current.stores.length).toBeGreaterThan(0),
    );

    const asaNorte = result.current.stores.find((s) => s.lojaId === 3);
    // Se "now real" estiver dentro da janela E 10:00 for há mais de 90min:
    // staleLive deve ser não-null. Se "now real" estiver antes das 08h ou
    // antes de 11:30 (10:00 + 90min), o teste passará com staleLive=null
    // sem falso-positivo.
    const realNow = new Date();
    const realHour = realNow.getHours() + realNow.getMinutes() / 60;
    const isInCommercialWindow = realHour > 8 && realHour < 23;
    // A "10:00" do flash está há MAIS de 90min apenas se now >= 11:30
    const flashDate1000 = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 10, 0, 0);
    const minutesSince1000 = (realNow.getTime() - flashDate1000.getTime()) / 60_000;
    const expectStale = isInCommercialWindow && minutesSince1000 > TV_FLASH_STALE_MINUTES;

    if (expectStale) {
      expect(asaNorte?.staleLive).not.toBeNull();
      expect(typeof asaNorte?.staleLive?.since).toBe('string');
      // Deve haver exceção âmbar com kind='stale-data' e lojaId=3
      const staleException = result.current.exceptions.items.find(
        (e) => e.kind === 'stale-data' && e.lojaId === 3,
      );
      expect(staleException).toBeDefined();
      expect(staleException?.severity).toBe('amber');
      expect(staleException?.message).toContain('Momma Asa Norte');
    } else {
      // Fora da janela ou ainda não passou os 90min → staleLive=null
      expect(asaNorte?.staleLive).toBeNull();
    }

    unmount();
  });
});

