    if (asaNorte?.staleLive != null) {
      expect(typeof asaNorte.staleLive.since).toBe('string');
      // 'since' deve corresponder à hora parseada do flash (02:25)
      const since = new Date(asaNorte.staleLive.since);
      expect(since.getHours()).toBe(2);
      expect(since.getMinutes()).toBe(25);
    }

    // Asa Sul com atualização recente → staleLive deve ser null
    expect(asaSul?.staleLive).toBeNull();

    // Canal não-live (linx-lagged) nunca tem staleLive — propriedade é null
    // (apenas lojas degust-live podem ter staleLive, todas as outras são null)
    for (const store of result.current.stores) {
      if (store.channel !== 'degust-live') {
        expect(store.staleLive).toBeNull();
      }
    }

    unmount();
  });

